2 · Who explains the gap?

// B vs A per month, split exactly: White's part gap_W = log(W_B/W_A) and Black's gap_B = log(B_B/B_A)
// stack to the net gap_WxB = log(WxB_B/WxB_A). The same log-percent axis as panel 2's Attribution view.
cchart2 = (w, h, P) =&gt; {
  const L = plotLayout(P, h, w, { hDefault: 300, mlBanner: 68, mlK: 4.1 });
  const long = cmpRows.flatMap((d) =&gt; [
    { date: d.date, side: "W", v: d.gap_W },   // "W"/"B", not "White"/"Black" (Plot reads those as colours)
    { date: d.date, side: "B", v: d.gap_B },
  ]).filter((d) =&gt; Number.isFinite(d.v));
  const ext = d3.extent([...long.map((d) =&gt; d.v), ...cmpRows.map((d) =&gt; d.gap_WxB).filter(Number.isFinite),
    ...cmpRows.map((d) =&gt; Math.max(0, d.gap_W) + Math.max(0, d.gap_B)).filter(Number.isFinite),
    ...cmpRows.map((d) =&gt; Math.min(0, d.gap_W) + Math.min(0, d.gap_B)).filter(Number.isFinite), 0]);
  const cands = [-0.99, -0.98, -0.95, -0.9, -0.8, -0.75, -0.6, -0.5, -0.33, -0.2, -0.1, 0, 0.1, 0.25, 0.5, 1, 1.5, 2, 3, 4, 9, 19, 49, 99];
  const slack = P && !P.legacy ? 0 : 0.05;
  const ticks = cands.map((p) =&gt; Math.log(1 + p)).filter((t) =&gt; t &gt;= ext[0] - slack && t &lt;= ext[1] + slack);
  // a gap between two sets can span a wide range, where the candidates crowd around 0: keep 0, then walk
  // outwards keeping only ticks at least 1/(k-1) of the range apart (k = the tick budget)
  const minGap = 0.9 * (ext[1] - ext[0]) / Math.max(1, thinScreen(P, L) - 1);
  const walk = (side) =&gt; { const out = []; let last = 0;
    for (const t of side) if (Math.abs(t - last) &gt;= minGap) { out.push(t); last = t; }
    return out; };
  const spaced = [...walk(ticks.filter((t) =&gt; t &lt; 0).sort((a, b) =&gt; b - a)).reverse(), ...(ticks.includes(0) ? [0] : []),
    ...walk(ticks.filter((t) =&gt; t &gt; 0).sort((a, b) =&gt; a - b))];
  return Plot.plot({
    width: w, ...L,
    x: { type: "utc", label: null, domain: [monthDate(ix, m0), d3.utcMonth.offset(monthDate(ix, m1), 1)], ...xTicks(P, w, L.marginLeft) },
    y: { label: "B vs A (log scale)", ticks: spaced, tickFormat: gapPct, grid: true },
    color: { domain: ["W", "B"], range: [COL.white, COL.black] },
    marks: [
      Plot.rectY(long, { x: "date", interval: "month", y: "v", fill: "side", order: ["W", "B"], insetLeft: 0.5, insetRight: 0.5, fillOpacity: 0.9 }),
      Plot.ruleY([0], { stroke: COL.ink, strokeOpacity: 0.4 }),
      Plot.lineY(cmpRows, { x: (d) =&gt; d3.utcDay.offset(d.date, 14), y: "gap_WxB", stroke: COL.ink, strokeWidth: 1.5 }),
      Plot.ruleX(cmpRows, Plot.pointerX({ x: (d) =&gt; d3.utcDay.offset(d.date, 14), stroke: COL.muted, strokeWidth: 1 })),
      Plot.tip(cmpRows, Plot.pointerX({ x: (d) =&gt; d3.utcDay.offset(d.date, 14), y: "gap_WxB",
        title: (d) =&gt; `${d.label}  (B vs A)\nNet, W×B  ${gapPct(d.gap_WxB)}   A ${pct(d.a_WxB)} · B ${pct(d.b_WxB)}\nWhite (W)  ${gapPct(d.gap_W)}   A ${pct(d.a_W)} · B ${pct(d.b_W)}\nBlack (B)  ${gapPct(d.gap_B)}   A ${pct(d.a_B)} · B ${pct(d.b_B)}\n(log parts add: ${d.gap_W?.toFixed(3)} + ${d.gap_B?.toFixed(3)} = ${d.gap_WxB?.toFixed(3)})` })),
    ],
  });
}







