3 · How does it score, A vs B?

cScoreDomain = {
  const v = cmpRows.flatMap((d) =&gt; [d.a_score_lo, d.a_score_hi, d.b_score_lo, d.b_score_hi]).filter(Number.isFinite);
  const lo = v.length ? d3.min(v) : 0.5, hi = v.length ? d3.max(v) : 0.5, padY = 0.1 * (hi - lo);
  let a = lo - padY, b = hi + padY;
  if (b - a &lt; 0.04) { const mid = (lo + hi) / 2; a = mid - 0.02; b = mid + 0.02; }
  if (a &lt; 0) { b = Math.min(1, b - a); a = 0; }
  if (b &gt; 1) { a = Math.max(0, a - (b - 1)); b = 1; }
  return [a, b];
}
cScoreTicks = (k) =&gt; {
  const [a, b] = cScoreDomain;
  for (const st of [0.01, 0.02, 0.05, 0.1, 0.2]) {
    const t = d3.range(Math.ceil(a / st - 1e-9), Math.floor(b / st + 1e-9) + 1).map((i) =&gt; +(i * st).toFixed(2));
    if (t.length &lt;= k || st === 0.2) return t;
  }
}
